#!/usr/bin/env bash
# Regenerate the generated LGX documentation, then prove the committed files match:
#
#   docs/lgx-reference.md   the LGX reference — template tags, directives, event modifiers,
#                           triggers, UI verbs, page queries, loop bindings, filters — generated by
#                           crates/logicaffeine_tests/tests/lgx_reference_lock.rs, which parses every
#                           example with the real parser and reads each row off the result
#   docs/lgx-stdlib.md      the definition tables of forms.lg, ui.lg and session.lg, generated from
#                           the modules' own `## Note`s by lgx_stdlib_guide_lock.rs (the prose
#                           around the tables is hand-written and left as it is)
#
# Each lock writes its file when LOGOS_REGEN=1 is set and then compares; the plain run afterwards
# proves the committed text is the generated text byte for byte.
set -euo pipefail
cd "$(dirname "$0")/../../.."

LOGOS_REGEN=1 cargo test -p logicaffeine-tests --test lgx_reference_lock \
    the_committed_reference_is_the_generated_reference -- --exact
LOGOS_REGEN=1 cargo test -p logicaffeine-tests --test lgx_stdlib_guide_lock \
    each_generated_table_is_the_modules_own_notes -- --exact
cargo test -p logicaffeine-tests --test lgx_reference_lock --test lgx_stdlib_guide_lock

echo "docs/lgx-reference.md and docs/lgx-stdlib.md regenerated; lgx_reference_lock and lgx_stdlib_guide_lock green"
